import React from "react";
import { Link } from "react-router-dom";
// import Logo from "../assets/img/accel_logo.png";
import Logo from "../../assets/img/accel_logo.png";

// import Avatar from "../assets/avatar.jpg";  // remplace par ton avatar

export default function Navbar() {
  return (
    <header className="fixed top-0 left-0 right-0 z-50">
      <nav className="bg-[##20264e] shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="h-16 flex items-center justify-between">
            {/* LEFT: logo + title */}
            <div className="flex items-center gap-4 min-w-0">
              <Link to="/" className="flex items-center gap-3">
                <img src={Logo} alt="logo" className="h-10 w-10 object-contain" />
                <span className="text-white text-xl font-semibold tracking-wide whitespace-nowrap">
                  AccelConnect
                </span>
              </Link>
            </div>

            {/* CENTER: search bar */}
            <div className="flex-1 flex justify-center px-4">
              <div className="w-full max-w-xl">
                <label htmlFor="site-search" className="sr-only">Rechercher</label>
                <div className="relative">
                  <input
                    id="site-search"
                    type="search"
                    placeholder="Rechercher..."
                    className="w-full rounded-full bg-white/95 text-sm placeholder-gray-500 py-3 pl-6 pr-12 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-400"
                  />
                  <button
                    type="button"
                    aria-label="search"
                    className="absolute right-2 top-1/2 -translate-y-1/2 h-9 w-9 rounded-full flex items-center justify-center hover:scale-95 transition"
                  >
                    {/* loupe SVG */}
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-700" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-4.35-4.35M11 19a8 8 0 100-16 8 8 0 000 16z" />
                    </svg>
                  </button>
                </div>
              </div>
            </div>

            {/* RIGHT: avatar */}
            {/* <div className="flex items-center gap-4">
              <div className="hidden md:block text-sm text-white/80"> </div>
              <button className="h-11 w-11 rounded-full overflow-hidden border-2 border-white/20 shadow-sm">
                <img src={Avatar} alt="avatar" className="h-full w-full object-cover" />
              </button>
            </div> */}
          </div>
        </div>
      </nav>
    </header>
  );
}
